class SanPham:
    def __init__(self, ten, gia):
        self.ten = ten
        self.gia = gia

    def __str__(self):
        return f"Tên: {self.ten}, Giá: {self.gia}"

    def __eq__(self, other):
        if not isinstance(other, SanPham):
            return False
        return self.ten == other.ten and self.gia == other.gia

class HangTapHoa(SanPham):
    def __init__(self, ten, gia, so_luong):
        super().__init__(ten, gia)
        self.so_luong = so_luong

    def __str__(self):
        return f"Tên: {self.ten}, Giá: {self.gia}, Số lượng: {self.so_luong}"

    def __eq__(self, other):
        # So sánh dựa trên SanPham (tên, giá) và thêm điều kiện số lượng
        return super().__eq__(other) and self.

