def tinh_tong_tien(so_du, so_tien_moi):
    # Điểm dừng: Nếu không còn phần tử nào
    if so_du == 0:
        return so_tien_moi

    # Bước đệ quy: Lấy phần tử đầu tiên cộng với tổng của phần còn lại
    return so_tien_moi + tinh_tong_tien(so_du - 1)
