def kiem_tra_nhiet_do(func):
    def wrapper(temp, muc_tieu):
        # Gọi hàm gốc để lấy giá trị nhiệt độ hiện tại
        temp = func(temp, muc_tieu)
        # Nếu thỏa mãn điều kiện, trả về giá trị đó
        if temp >= muc_tieu:
            return temp
        return "Lỗi: Nhiệt độ không hợp lệ"
    return wrapper

@kiem_tra_nhiet_do
def lay_nhiet_do(temp):
    # Trả về giá trị nhiệt độ thực tế (không tính phần âm)
    return temp
```

