def kiem_tra_don_hang(ma1, ma2):
    # Nếu độ dài khác nhau thì chắc chắn không phải anagram
    if len(ma1) != len(ma2):
        return False

    # Sắp xếp các ký tự trong chuỗi và so sánh hai danh sách kết quả
    return sorted(ma1) == sorted(ma2)
